import fs from 'fs/promises';
import path from 'path';
import { createHash } from 'crypto';
import type { GuidanceAttachment, GuidanceDocument } from '../types/guidance';
import { GUIDANCE_IMAGE_BYTES } from '../types/guidance';
import {
  PROFILE_UPLOAD_BYTES,
  PROFILE_UPLOAD_COUNT,
} from '../types/design-profile';
import type { ChangeRequest } from '../types/change-request-types';
import { ProfileMedia, describeProfileImage } from './profiles/ProfileMedia';
import { guidanceAssetError, guidanceImageReferences } from './guidanceImages';
import { errorMessage } from '../utils/errorMessage';
import { materializeGuidanceReferences } from './guidanceReferences';

export const guidanceAttachments = (
  documents: readonly GuidanceDocument[],
): GuidanceAttachment[] => {
  const images = new Map<string, GuidanceAttachment>();
  for (const document of documents)
    for (const image of document.attachments ?? [])
      if (!images.has(image.hash)) images.set(image.hash, image);
  return [...images.values()];
};

export const readGuidanceImage = async (
  image: GuidanceAttachment,
): Promise<Buffer> => {
  try {
    const stat = await fs.lstat(image.path);
    if (
      !stat.isFile() ||
      stat.size !== image.bytes ||
      stat.size > GUIDANCE_IMAGE_BYTES
    )
      throw new Error('File is missing, changed, or exceeds 10 MiB.');
    const bytes = await fs.readFile(image.path);
    const descriptor = describeProfileImage(bytes);
    if (
      descriptor.hash !== image.hash ||
      descriptor.mimeType !== image.mimeType
    )
      throw new Error('Image content does not match its saved version.');
    return bytes;
  } catch (error) {
    throw guidanceAssetError(
      image.source,
      errorMessage(error, 'Cannot read image.'),
    );
  }
};

export const snapshotGuidance = async (args: {
  documents: GuidanceDocument[];
  dataDirectory: string;
}): Promise<GuidanceDocument[]> => {
  for (const document of args.documents) {
    const references = guidanceImageReferences(document.markdown);
    if (
      references.length !== (document.attachments?.length ?? 0) ||
      references.some((reference, index) => {
        const image = document.attachments?.[index];
        return (
          reference.source !== image?.source ||
          reference.alt !== image.alt ||
          reference.title !== image.title
        );
      })
    )
      throw guidanceAssetError(
        document.title,
        'The saved Markdown and attachments do not match. Update this document with --file to import its illustrations.',
      );
  }
  const media = new ProfileMedia(
    path.join(args.dataDirectory, 'guidance-images'),
  );
  const paths = new Map<string, string>();
  for (const image of guidanceAttachments(args.documents)) {
    const bytes = await readGuidanceImage(image);
    const stored = await media.put(bytes);
    paths.set(image.hash, await media.resolve(stored));
  }
  return materializeGuidanceReferences({
    dataDirectory: args.dataDirectory,
    documents: args.documents.map((document) => ({
      ...document,
      ...(document.attachments?.length
        ? {
            attachments: document.attachments.map((image) => ({
              ...image,
              path: paths.get(image.hash) ?? image.path,
            })),
          }
        : {}),
    })),
  });
};

export const validateGuidanceBudget = (request: ChangeRequest): void => {
  const required = guidanceAttachments(request.guidance ?? []);
  if (!required.length) return;
  for (const change of request.changes) {
    if (change.kind !== 'comment') continue;
    const sizes = new Map(required.map((image) => [image.hash, image.bytes]));
    for (const dataUrl of change.images ?? []) {
      const bytes = Buffer.from(
        dataUrl.slice(dataUrl.indexOf(',') + 1),
        'base64',
      );
      sizes.set(createHash('sha256').update(bytes).digest('hex'), bytes.length);
    }
    if (
      sizes.size > PROFILE_UPLOAD_COUNT ||
      [...sizes.values()].reduce((sum, bytes) => sum + bytes, 0) >
        PROFILE_UPLOAD_BYTES
    )
      throw guidanceAssetError(
        'selected documents',
        'Combined guidance and request images exceed the 35 MiB or 100-image budget. Exclude documents or reduce attachments.',
      );
  }
};
